// 899371 enrichment P13 (docs/enterprise-899371-enrichment-plan.md §9) — the TRACE INDEX of a learning course: the recorded
// step-by-step runs of its questions, server-side only (api/src/data/learning-trace/<courseId>.json, generated by
// scripts/build-learning-trace-index.mjs from the Docker-recorded runs). A trace is keyed by the page and the C# code block it runs:
//   • kind "exercise" — a self-study exercise's program; it shows the answer, so a student gets it only after answering that exercise
//     (the server's own study record: completed or revealed);
//   • kind "book" — a book tracing question's program; closed to students until the teacher releases that module (decision D1).
// Pure readers; the route decides who may read what.
const ID = /^[A-Za-z0-9_-]{1,64}$/;
const cleanId = v => String(v || "").trim();
const CACHE = new Map();

/** The course's trace index, or null (no index / malformed). Cached per process. */
function loadTraceIndex(courseId) {
  const id = cleanId(courseId);
  if (!ID.test(id)) return null;
  if (CACHE.has(id)) return CACHE.get(id);
  let index = null;
  try { index = require("../data/learning-trace/" + id + ".json"); } catch { index = null; }
  if (!index || index.schemaVersion !== 1 || index.courseId !== id || !index.traces || typeof index.traces !== "object") index = null;
  CACHE.set(id, index);
  return index;
}

/** One trace entry by page and block, or null (unknown ids are never echoed). */
function findTrace(index, pageId, blockId) {
  const p = cleanId(pageId), b = cleanId(blockId);
  if (!index || !ID.test(p) || !ID.test(b)) return null;
  const t = index.traces[p + "/" + b];
  return t && typeof t === "object" && (t.kind === "exercise" || t.kind === "book") && typeof t.moduleId === "string" ? t : null;
}

/**
 * What one actor may do with each trace: "open" (may watch now) or "answer-first" (an exercise not answered yet). A trace the actor
 * may not see at all is absent. `canSee(moduleId)`, `answered(pageId, activityId)` and `released(moduleId)` are the caller's gates.
 */
function traceStates(index, { canSee, answered, released, teacher }) {
  const out = {};
  if (!index) return out;
  for (const [key, t] of Object.entries(index.traces)) {
    if (!t || (t.kind !== "exercise" && t.kind !== "book")) continue;
    if (teacher) { out[key] = "open"; continue; }
    if (!canSee(t.moduleId)) continue;
    const pageId = key.split("/")[0];
    if (t.kind === "exercise") out[key] = answered(pageId, t.activityId) ? "open" : "answer-first";
    else if (released(t.moduleId)) out[key] = "open";
  }
  return out;
}

module.exports = { loadTraceIndex, findTrace, traceStates };
